export function getPageForSurahAyah(surahNumber: number, ayahNumber: number = 1): number {
  const breaks = SURAH_PAGE_BREAKS[surahNumber];
  if (!breaks || breaks.length === 0) {
    const s = ALL_SURAHS_LIST.find((item) => item.number === surahNumber);
    return s?.pageStart || 1;
  }
  const targetAyah = Math.max(1, ayahNumber);
  let matchedPage = breaks[0][1];
  for (let i = 0; i < breaks.length; i++) {
    if (breaks[i][0] <= targetAyah) {
      matchedPage = breaks[i][1];
    } else {
      break;
    }
  }
  return matchedPage;
}
